  [30001] = { "敵を恐怖に陥れ、最大$D1の間、恐怖で逃げ回らせます。一度に恐怖状態にできる対象は1体だけです。", "恐怖で逃げ惑っています。", 0x7ea26162, 0xfa67e4a8, "uu" },
