  [30081] = { "敵を$D1の間病気に冒し、受けるPhysicalダメージを$N2増加させ、スタミナを$N3低下させます。病気にかかった対象は、戦闘で攻撃を受けると$N4%の確率で周囲の味方の一体に病気を広めます。", "受ける物理ダメージが$N1増加します。\nスタミナが$N2減少します。\n攻撃が命中すると$N3%の確率でRetching Plagueを広めます。", 0x9ac57eb9, 0x56b2b975, "uu" },
  [30088] = { "$N1時間の間、スタミナを上昇させます。", "スタミナが$N1増加します。", 0x6b6d247c, 0x4cdb5a52, "uu" },
  [30089] = { "$N1時間の間、スタミナを上昇させます。", "スタミナが$N1増加します。", 0x6b6d247c, 0x543f3a70, "uu" },
  [30090] = { "$N1時間の間、スタミナを上昇させます。", "スタミナが$N1増加します。", 0x6b6d247c, 0x543f3a70, "uu" },
